from datetime import datetime, timedelta

class Scheduler:
    def __init__(self) -> None:
        """Initialize the scheduler with empty appointment book."""
        self.appointments = {}
        self.appointment_id = 0
        self.patient_appointments = {}

    def book(self, patient: str, doctor: str, start: datetime, end: datetime, now: datetime) -> int:
        """
        Book an appointment; returns its id. `now` is the current time.

        Raises:
            ValueError: If the appointment overlaps another appointment of the same doctor.
            ValueError: If the patient already has an upcoming appointment.
        """
        if patient in self.patient_appointments:
            upcoming_appointment = self.patient_appointments[patient]
            if upcoming_appointment['start'] > now:
                raise ValueError("Patient already has an upcoming appointment")

        if self.is_free(doctor, start, end):
            self.appointment_id += 1
            self.appointments[self.appointment_id] = {'patient': patient, 'doctor': doctor, 'start': start, 'end': end, 'cancelled': False}
            self.patient_appointments[patient] = self.appointments[self.appointment_id]
            return self.appointment_id
        else:
            raise ValueError("Appointment overlaps another appointment of the same doctor")

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """
        Cancel an appointment.

        Does not free the time slot if the appointment is less than 24 hours before its start.
        """
        if appointment_id in self.appointments:
            appointment = self.appointments[appointment_id]
            if appointment['start'] - now < timedelta(hours=24):
                appointment['cancelled'] = True
            else:
                del self.appointments[appointment_id]
                del self.patient_appointments[appointment['patient']]
        else:
            raise ValueError("Appointment does not exist")

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """
        True if the doctor can be booked between start and end.

        Appointments that only touch (one ends exactly when the other starts) do not overlap.
        """
        for appointment in self.appointments.values():
            if appointment['doctor'] == doctor and not appointment['cancelled']:
                if (start < appointment['end'] and end > appointment['start']):
                    return False
        return True
